        demanda_objetos_compania: null,
        comprende_prohibiciones: null,
        sonrie_balbucea: null,
        descoordinacion_ojomano: null,
      },
    },
    vision_audicion: {
      estimulos_visuales: null,
      estimulos_auditivos: null,
      ojos_irritados_llorosos: null,
      reconoce_sonidos_familiares: null,
      dolores_cabeza: null,
      gira_cabeza_llamado_ruido: null,
      acerca_aleja_objetos: null,
      acerca_oidos_fuente_sonido: null,
      sigue_desplazamiento: null,
      tapa_golpea_oidos: null,
      dolores_oidos_frecuentes: null,
      movimientos_oculares_anormales: null,
      conductas_erroneas: null,
      pronunciacion_adecuada: null,
      dx_visual: null,
      dx_auditivo: null,
      observaciones: "",
    },
    lenguaje: {
      modo_comunicacion: "", // oral | gestual | mixto | otro
      otro_modo: "",
      expresivo: {
        balbucea_sonidos: null,
        emite_frases: null,
        gestos_senas_aisladas: null,
        relata_experiencias: null,
        emite_palabras_senas: null,
        emision_pronunciacion_clara: null,
      },
      comprensivo: {
        identifica_objetos: null,
        sigue_instrucciones_simples: null,
        identifica_personas: null,
        sigue_instrucciones_complejas: null,
        comprende_conceptos_abstractos: null,
        sigue_instrucciones_grupales: null,
        responde_preguntas_vida_diaria: null,
        comprende_relatos_noticias_cuentos: null,
      },
      perdida_lenguaje: { hubo: false, edad_motivo: "" },
      observaciones: "",
    },
    desarrollo_social: {
      se_relaciona_entorno: null,
      relacion_colaborativa: null,
      explica_razones: null,
      respeta_normas_sociales: null,
      participa_actividades_grupales: null,
      respeta_normas_escolares: null,
      opta_trabajo_individual: null,
      sentido_humor: null,
      lenguaje_ecolalico: null,
      movimientos_estereotipados: null,
      dificultad_adaptarse: null,
      pataletas_frecuentes: null,
      reaccion_estimulos: { luces: "", sonidos: "", personas_extranias: "" }, // natural | desmesurada
      observaciones: "",
    },
    estado_actual_salud: {
      vacunas_al_dia: null,
      trastorno_motor: null,
      epilepsia: null,
      problema_bronco_respiratorio: null,
      problemas_cardiacos: null,
      enfermedad_infecto_contagiosa: null,
      paraplejia: null,
      trastorno_emocional: null,
      perdida_auditiva: null,
      trastorno_conductual: null,
      perdida_visual: null,
      otro: "",
      control_tratamiento: "",
      alimentacion: "", // normal | malo | bueno | otro
      alimentacion_otro: "",
      peso_apreciacion: "", // normal | bajo | obesidad
      suenio: { tipo: "", horas: "", insomnio: false, pesadillas: false, terrores_nocturnos: false, sonambulismo: false, despierta_buen_humor: false, duerme: "", especificar: "" },
      humor: { alegre: false, jugueton: false, risueno: false, triste: false, serio: false, rebelde: false, apatico: false, violento: false, otro: "" },
      observaciones: "",
    },
  });

  const [familia, setFamilia] = useState({
    convivientes: [], // [{id, nombre, parentesco, edad, escolaridad, ocupacion}]
    salud_familia: "",
    observaciones: "",
  });

  const [escolar, setEscolar] = useState({
    trayectoria: {
      edad_ingreso: "",
      asistio_jardin: null,
      numero_colegios: "",
      modalidad: "", // regular | especial | tecnica | otro
      modalidad_otro: "",
      motivo_cambios: "",
      repitio: null,
      cursos_repetidos: "",
      motivo_repeticion: "",
    },
    situacion_actual: {
      nivel_curso: "",
      dif_aprendizaje: null,
      dif_participar: null,
      conducta_disruptiva: null,
      asiste_regularmente: null,
      asiste_con_agrado: null,
      apoyo_familiar_tareas: null,
      amigos: null,
    },
    actitud_familiar: {
      evalua_desempeno: "", // satisfactorio | insatisfactorio
      evalua_motivos: "",
      respuesta_dificultades: [], // apoyo | castigo | indiferencia | compasion | tension | otra
      respuesta_dificultades_otra: "",
      respuesta_exitos: [], // apoyo | indiferencia | otra
      respuesta_exitos_otra: "",
      refuerzos_premios: { afectivas: false, alimentos: false, ver_tv: false, juguetes: false, tiempo_libre: false, otros: "" },
      quienes_apoyan: { madre: false, padre: false, hermanos: false, otros_familiares: false, otros_profesionales: false },
      expectativas: "", // alta | mediana | baja
      ambiente_aprendizaje: "", // ambos | solo_fisico | solo_emocional
    },
    comentarios_observaciones: "",
  });

  // Handlers para futura conexión
  const guardarCabecera = () => console.log("Guardar Anamnesis", anamnesisCabecera);
  const handleSave = (seccion, payload) => console.log("Guardar", seccion, payload);
  const handleDelete = (seccion, id) => console.log("Eliminar", seccion, id);

  return (
    <div className="contenedor">
      <h2 className="titulo">Anamnesis</h2>
      <p className="subtitulo">
        Entrevista a la familia / síntesis de antecedentes de salud, escolares y sociales del estudiante.
      </p>

      {/* Cabecera (fecha + acciones rápidas) */}
      <div className="card mb">
        <div className="card-body">
          <div className="fila">
            <div className="col">
              <label>Fecha</label>
              <input
                type="date"
                value={anamnesisCabecera.fecha}
                onChange={(e) => setAnamnesisCabecera({ ...anamnesisCabecera, fecha: e.target.value })}
              />
            </div>
            <div className="col acciones">
              <button className="btn secundario" onClick={guardarCabecera}>Guardar cabecera</button>
              <button className="btn" onClick={() => console.log("Generar PDF (futuro)")}>Generar PDF</button>
            </div>
          </div>
        </div>
      </div>

      {/* Tabs (CSS puro) */}
      <div className="tabs">
        <div className="tab-list">
          <button className={`tab ${tab === "identificacion" ? "activa" : ""}`} onClick={() => setTab("identificacion")}>1. Identificación del Estudiante</button>
          <button className={`tab ${tab === "informantes" ? "activa" : ""}`} onClick={() => setTab("informantes")}>2. Informantes</button>
          <button className={`tab ${tab === "entrevistadores" ? "activa" : ""}`} onClick={() => setTab("entrevistadores")}>3. Entrevistadores</button>
          <button className={`tab ${tab === "definicion" ? "activa" : ""}`} onClick={() => setTab("definicion")}>4. Definición del Problema</button>
          <button className={`tab ${tab === "salud" ? "activa" : ""}`} onClick={() => setTab("salud")}>5. Salud y Desarrollo</button>
          <button className={`tab ${tab === "familia" ? "activa" : ""}`} onClick={() => setTab("familia")}>6. Antecedentes Familiares</button>
          <button className={`tab ${tab === "escolar" ? "activa" : ""}`} onClick={() => setTab("escolar")}>7. Antecedentes Escolares</button>
          <button className={`tab ${tab === "observaciones" ? "activa" : ""}`} onClick={() => setTab("observaciones")}>8. Observaciones</button>
        </div>

        <div className="tab-panel">
          {tab === "identificacion" && (
            <IdentificacionEstudianteSection
              value={identificacion}
              setValue={setIdentificacion}
              onSave={() => handleSave("identificacion_estudiante", identificacion)}
            />
          )}

          {tab === "informantes" && (
            <InformantesSection
              items={informantes}
              setItems={setInformantes}
              onSave={() => handleSave("informantes", informantes)}
              onDelete={(id) => handleDelete("informantes", id)}
            />
          )}

          {tab === "entrevistadores" && (
            <EntrevistadoresSection
              items={entrevistadores}
              setItems={setEntrevistadores}
              onSave={() => handleSave("entrevistadores", entrevistadores)}
              onDelete={(id) => handleDelete("entrevistadores", id)}
            />
          )}

          {tab === "definicion" && (
            <DefinicionProblemaSection
              value={anamnesisCabecera.definicion_problema}
              setValue={(v) => setAnamnesisCabecera({ ...anamnesisCabecera, definicion_problema: v })}
              onSave={() => handleSave("definicion_problema", { definicion_problema: anamnesisCabecera.definicion_problema })}
            />
          )}

          {tab === "salud" && (
            <SaludDesarrolloSection
              value={saludDesarrollo}
              setValue={setSaludDesarrollo}
              onSave={() => handleSave("salud_desarrollo", saludDesarrollo)}
            />
          )}

          {tab === "familia" && (
            <AntecedentesFamiliaSection
              value={familia}
              setValue={setFamilia}
              onSave={() => handleSave("antecedentes_familia", familia)}
              onDelete={(id) => {
                const nuevo = familia.convivientes.filter((p) => p.id !== id);
                setFamilia({ ...familia, convivientes: nuevo });
                handleDelete("antecedentes_familia_persona", id);
              }}
            />
          )}

          {tab === "escolar" && (
            <AntecedentesEscolaresSection
              value={escolar}
              setValue={setEscolar}
              onSave={() => handleSave("antecedentes_escolares", escolar)}
            />
          )}

          {tab === "observaciones" && (
            <ObservacionesGeneralesSection
              value={anamnesisCabecera.observaciones_generales}
              setValue={(v) => setAnamnesisCabecera({ ...anamnesisCabecera, observaciones_generales: v })}
              onSave={() =>
                handleSave("observaciones_generales", { observaciones_generales: anamnesisCabecera.observaciones_generales })
              }
            />
          )}
        </div>
      </div>
    </div>
  );
}
